package com.radiomaster.app.ui.globe

import android.content.Context
import androidx.compose.ui.graphics.Path
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject

/**
 * Offline land polygons for the map backdrop.
 *
 * The asset is generated by `tools/generate_world_map.py` from the world-atlas (Natural Earth)
 * quantized TopoJSON and stores integer coordinates on a fixed grid, which keeps 117 polygons and
 * ~4 800 points in 47 KB of text instead of a multi-megabyte GeoJSON. Polygons are already split at
 * the antimeridian, so no ring wraps across the map — a `Path` can be drawn per ring without
 * clipping artefacts.
 */
class WorldBackdrop(val polygons: List<List<FloatArray>>) {
    val isEmpty: Boolean get() = polygons.isEmpty()
}

object WorldBackdropLoader {

    private const val ASSET = "world_land.json"

    /** Cached across recompositions and screens; decoding is a one-off cost per process. */
    @Volatile
    private var cached: WorldBackdrop? = null

    suspend fun load(context: Context): WorldBackdrop = withContext(Dispatchers.IO) {
        cached ?: run {
            val backdrop = runCatching { decode(context.applicationContext.assets.open(ASSET)) }
                .getOrDefault(WorldBackdrop(emptyList()))
            cached = backdrop
            backdrop
        }
    }

    /**
     * Reads the generated file. `org.json` is used rather than Gson because the asset is a plain
     * array of integer pairs: a streaming parse avoids declaring a throwaway DTO whose no-arg
     * constructor Gson would have to reach for by reflection.
     */
    private fun decode(source: java.io.InputStream): WorldBackdrop =
        source.bufferedReader().use { reader ->
            val root = JSONObject(reader.readText())
            val grid = root.optInt("grid", 0)
            if (grid <= 0) return WorldBackdrop(emptyList())
            val rings = root.optJSONArray("polygons") ?: return WorldBackdrop(emptyList())
            val polygons = ArrayList<List<FloatArray>>(rings.length())
            for (i in 0 until rings.length()) {
                val flat = rings.getJSONArray(i)
                if (flat.length() < 6) continue // need at least a closed triangle
                val points = ArrayList<FloatArray>(flat.length() / 2)
                for (j in 0 until flat.length() - 1 step 2) {
                    points.add(
                        floatArrayOf(
                            flat.getInt(j) / grid.toFloat(),
                            flat.getInt(j + 1) / grid.toFloat(),
                        ),
                    )
                }
                polygons.add(points)
            }
            WorldBackdrop(polygons)
        }
}

/** Builds the closed [Path] of one ring in screen space; the map is drawn with a flat transform. */
fun pathFor(
    ring: List<FloatArray>,
    originX: Float,
    originY: Float,
    worldWidth: Float,
    worldHeight: Float,
): Path {
    val path = Path()
    var started = false
    for (point in ring) {
        val x = originX + point[0] * worldWidth
        val y = originY + point[1] * worldHeight
        if (!started) {
            path.moveTo(x, y)
            started = true
        } else {
            path.lineTo(x, y)
        }
    }
    if (started) path.close()
    return path
}
